"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "../three/ChunkLoader";
import { createRenderer } from "../three/Renderer";
import { createCamera } from "../three/Camera";
import { createScene } from "../three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { createWeatherLoader } from "./three/WeatherRenderer";
import { LightingManager } from "./LightingManager";
import {
  setLayerVisibility,
  cleanupUnusedChunks,
  createGround,
  updateRoadVisibility,
  generateTilesToLoad,
} from "./sceneUtils";
import {
  PROJECTIONS,
  DEFAULTS,
  ROAD_VISIBILITY,
  WEATHER_CONFIG,
  GROUND_CONFIG,
} from "./constants";

export default function ThreeScene({ settings = {} }) {
  const containerRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);
  const controlsRef = useRef(null);
  const sceneRef = useRef(null);
  const cubeRef = useRef(null);
  const frameRef = useRef(null);
  const updateTimeoutRef = useRef(null);
  const controllerRef = useRef(null);
  const isLoadingRef = useRef(false);
  const lightingRef = useRef(null);
  const groundRef = useRef(null);

  const loadersRef = useRef(new Map());

  const [status, setStatus] = useState({
    chunks: 0,
    meshes: 0,
    features: 0,
    lastQueryMs: 0,
    buildings: 0,
    roads: 0,
    water: 0,
    weather: 0,
  });

  // Обработка видимости зданий
  useEffect(() => {
    const bLoader = loadersRef.current.get("buildings");
    if (!bLoader?.meshGroups) return;

    const visible = settings.buildings !== false;
    setLayerVisibility(bLoader.meshGroups, visible);
  }, [settings.buildings]);

  // Обработка режимов погоды (temperature/humidity)
  useEffect(() => {
    const weatherLoader = loadersRef.current.get("weather");
    if (!weatherLoader) return;

    const shouldShowWeather = settings.temperature || settings.humidity;

    if (!shouldShowWeather) {
      // Очищаем все погодные меши
      weatherLoader.clearAll?.();
      return;
    }

    // Определяем режим отображения
    const mode = settings.temperature ? "temperature" : "humidity";

    // Если у лоадера есть метод смены режима - используем
    if (typeof weatherLoader.setMode === "function") {
      weatherLoader.setMode(mode);
    } else {
      // Иначе пересоздаём лоадер с новым режимом
      weatherLoader.clearAll?.();
      weatherLoader.mode = mode;
    }

    // Перезагружаем погодные данные для текущей области
    const controls = controlsRef.current;
    if (!controls) return;

    const envBase = process.env.NEXT_PUBLIC_API_BASE || "http://127.0.0.1:8000";
    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "0");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "0");
    const [centerX, centerZ] = proj4(
      PROJECTIONS.WGS84,
      PROJECTIONS.WEB_MERCATOR,
      [startLon, startLat]
    );

    const tx = controls.target.x + centerX;
    const tz = controls.target.z + centerZ;
    const [lon, lat] = proj4(PROJECTIONS.WEB_MERCATOR, PROJECTIONS.WGS84, [
      tx,
      tz,
    ]);

    const tileSize = settings.tileSize || DEFAULTS.TILE_SIZE;
    const viewRadius =
      typeof settings.viewRadius === "number"
        ? settings.viewRadius
        : DEFAULTS.VIEW_RADIUS;

    const { tilesToLoad } = generateTilesToLoad(lon, lat, tileSize, viewRadius);

    // Асинхронно загружаем погодные тайлы
    Promise.all(
      tilesToLoad.map((tile) =>
        weatherLoader
          .loadChunk(tile.minLon, tile.minLat, tile.maxLon, tile.maxLat, {
            useCache: true,
            keyHint: `weather_${tile.key}`,
          })
          .catch((e) => console.warn("Weather tile load failed:", e))
      )
    );
  }, [settings.temperature, settings.humidity]);

  // Обработка ночного режима
  useEffect(() => {
    const lighting = lightingRef.current;
    if (!lighting) return;

    lighting.setNightMode(settings.nightMode === true);
  }, [settings.nightMode]);

  // Главная инициализация сцены
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const envBase = process.env.NEXT_PUBLIC_API_BASE || "http://127.0.0.1:8000";
    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "0");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "0");
    const [centerX, centerZ] = proj4(
      PROJECTIONS.WGS84,
      PROJECTIONS.WEB_MERCATOR,
      [startLon, startLat]
    );

    const endpoints = {
      buildings: settings.endpoints?.buildings || `${envBase}/chunk/buildings`,
      roads: settings.endpoints?.roads || `${envBase}/chunk/roads`,
      water: settings.endpoints?.water || `${envBase}/chunk/water`,
    };

    const getLoader = (layerKey, scene, opts = {}) => {
      if (settings.loaders?.[layerKey]) return settings.loaders[layerKey];
      return new ChunkLoader(scene, opts);
    };

    const renderer = createRenderer(container);
    rendererRef.current = renderer;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.0;

    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = DEFAULTS.CAMERA_FOV;
    camera.updateProjectionMatrix();
    camera.position.set(0, DEFAULTS.CAMERA_HEIGHT, DEFAULTS.CAMERA_DISTANCE);
    camera.lookAt(0, 0, 0);
    cameraRef.current = camera;

    const controls = createControls(camera, renderer.domElement);
    controls.target.set(0, 0, 0);
    controls.update();
    controlsRef.current = controls;

    const { scene, cube } = createScene();
    sceneRef.current = scene;
    cubeRef.current = cube;

    const lighting = new LightingManager(scene);
    lighting.setNightMode(settings.nightMode === true);
    lightingRef.current = lighting;

    const cleanupRaycast = setupRaycast(
      renderer.domElement,
      camera,
      scene,
      controls,
      container
    );

    const buildingsLoader = getLoader("buildings", scene, {
      url: endpoints.buildings,
      centerOffset: [centerX, centerZ],
      layerType: "buildings",
      onProgress: (meta) => {
        setStatus((s) => ({
          ...s,
          buildings: meta.rendered || 0,
          lastQueryMs: meta.queryTimeMs || s.lastQueryMs,
        }));
      },
    });

    const roadsLoader = getLoader("roads", scene, {
      url: endpoints.roads,
      centerOffset: [centerX, centerZ],
      layerType: "roads",
      onProgress: (meta) =>
        setStatus((s) => ({ ...s, roads: meta.rendered || 0 })),
    });

    const waterLoader = getLoader("water", scene, {
      url: endpoints.water,
      centerOffset: [centerX, centerZ],
      layerType: "rivers",
      onProgress: (meta) =>
        setStatus((s) => ({ ...s, water: meta.rendered || 0 })),
    });

    const initialWeatherMode = settings.temperature
      ? "temperature"
      : settings.humidity
      ? "humidity"
      : "none";

    const weatherLoader = createWeatherLoader(scene, {
      url: `${envBase}/weather/area`,
      centerOffset: [centerX, centerZ],
      minTemp: WEATHER_CONFIG.MIN_TEMP,
      maxTemp: WEATHER_CONFIG.MAX_TEMP,
      minHumidity: WEATHER_CONFIG.MIN_HUMIDITY,
      maxHumidity: WEATHER_CONFIG.MAX_HUMIDITY,
      tileSize: WEATHER_CONFIG.TILE_SIZE,
      elevationAboveGround: WEATHER_CONFIG.ELEVATION,
      opacity: WEATHER_CONFIG.OPACITY,
      mode: initialWeatherMode,
      step: WEATHER_CONFIG.STEP,
      onProgress: (meta) =>
        setStatus((s) => ({ ...s, weather: meta.rendered || 0 })),
    });

    loadersRef.current.set("buildings", buildingsLoader);
    loadersRef.current.set("roads", roadsLoader);
    loadersRef.current.set("water", waterLoader);
    loadersRef.current.set("weather", weatherLoader);

    if (typeof settings.onLoadersReady === "function") {
      try {
        settings.onLoadersReady({
          buildings: buildingsLoader,
          roads: roadsLoader,
          water: waterLoader,
          weather: weatherLoader,
        });
      } catch (e) {
        console.warn("onLoadersReady callback failed:", e);
      }
    }

    const ground = createGround(
      GROUND_CONFIG.SIZE,
      GROUND_CONFIG.COLOR,
      GROUND_CONFIG.Y_OFFSET
    );
    scene.add(ground);
    groundRef.current = ground;

    // Рендер-луп
    const loop = () => {
      if (!cubeRef.current || !sceneRef.current) return;

      cubeRef.current.rotation.y += 0.005;
      lighting.updateDirectionalLight(camera.position);

      // Обновление позиции земли
      if (groundRef.current) {
        groundRef.current.position.x = camera.position.x;
        groundRef.current.position.z = camera.position.z;
      }

      controls.update();

      // Обновление видимости дорог
      const rLoader = loadersRef.current.get("roads");
      updateRoadVisibility(rLoader, camera, ROAD_VISIBILITY);

      // Обновление видимости зданий
      const bLoader = loadersRef.current.get("buildings");
      if (bLoader?.meshGroups) {
        const buildingsEnabled = settings.buildings !== false;
        const visible =
          buildingsEnabled &&
          camera.position.y < DEFAULTS.HIDE_BUILDINGS_HEIGHT;
        setLayerVisibility(bLoader.meshGroups, visible);
      }

      renderer.render(scene, camera);
      frameRef.current = requestAnimationFrame(loop);
    };
    loop();

    // Функция загрузки чанков
    async function updateChunks() {
      if (isLoadingRef.current) return;
      isLoadingRef.current = true;

      if (controllerRef.current) {
        try {
          controllerRef.current.abort();
        } catch (e) {}
      }
      const controller = new AbortController();
      controllerRef.current = controller;

      try {
        const tx = controls.target.x + centerX;
        const tz = controls.target.z + centerZ;
        const [lon, lat] = proj4(PROJECTIONS.WEB_MERCATOR, PROJECTIONS.WGS84, [
          tx,
          tz,
        ]);

        const tileSize = settings.tileSize || DEFAULTS.TILE_SIZE;
        const viewRadius =
          typeof settings.viewRadius === "number"
            ? settings.viewRadius
            : DEFAULTS.VIEW_RADIUS;

        const { tilesToLoad, activeTiles } = generateTilesToLoad(
          lon,
          lat,
          tileSize,
          viewRadius
        );
        const shouldLoadWeather = settings.temperature || settings.humidity;

        const batchPromises = tilesToLoad.map((tile) => {
          const optsBase = { signal: controller.signal, useCache: true };

          const promises = [
            buildingsLoader.loadChunk(
              tile.minLon,
              tile.minLat,
              tile.maxLon,
              tile.maxLat,
              {
                ...optsBase,
                simplify: 2.0,
                keyHint: `buildings_${tile.key}`,
              }
            ),
            roadsLoader.loadChunk(
              tile.minLon,
              tile.minLat,
              tile.maxLon,
              tile.maxLat,
              {
                ...optsBase,
                simplify: 0.5,
                keyHint: `roads_${tile.key}`,
              }
            ),
            waterLoader.loadChunk(
              tile.minLon,
              tile.minLat,
              tile.maxLon,
              tile.maxLat,
              {
                ...optsBase,
                simplify: 0.0,
                keyHint: `water_${tile.key}`,
              }
            ),
          ];

          if (shouldLoadWeather) {
            promises.push(
              weatherLoader.loadChunk(
                tile.minLon,
                tile.minLat,
                tile.maxLon,
                tile.maxLat,
                {
                  ...optsBase,
                  keyHint: `weather_${tile.key}`,
                }
              )
            );
          }

          return Promise.all(promises);
        });

        await Promise.all(batchPromises);

        cleanupUnusedChunks(buildingsLoader, "buildings", activeTiles);
        cleanupUnusedChunks(roadsLoader, "roads", activeTiles);
        cleanupUnusedChunks(waterLoader, "water", activeTiles);
        if (shouldLoadWeather)
          cleanupUnusedChunks(weatherLoader, "weather", activeTiles);
      } catch (e) {
        if (e?.name !== "AbortError")
          console.error("[Scene] loadChunk error:", e);
      } finally {
        isLoadingRef.current = false;
      }
    }

    const debouncedUpdate = () => {
      if (updateTimeoutRef.current) clearTimeout(updateTimeoutRef.current);
      updateTimeoutRef.current = setTimeout(
        updateChunks,
        DEFAULTS.UPDATE_DEBOUNCE
      );
    };

    controls.addEventListener("change", debouncedUpdate);
    updateChunks();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };

    window.addEventListener("resize", handleResize);
    container.appendChild(renderer.domElement);

    // Cleanup
    return () => {
      cancelAnimationFrame(frameRef.current);
      clearTimeout(updateTimeoutRef.current);
      controls.removeEventListener("change", debouncedUpdate);
      window.removeEventListener("resize", handleResize);

      try {
        cleanupRaycast();
      } catch (e) {}
      try {
        controllerRef.current?.abort();
      } catch (e) {}

      for (const loader of loadersRef.current.values()) loader.clearAll?.();

      if (lighting) lighting.dispose();

      try {
        if (renderer.domElement && container.contains(renderer.domElement))
          container.removeChild(renderer.domElement);
      } catch (e) {}

      try {
        renderer.dispose();
      } catch (e) {}
      try {
        cube?.geometry.dispose();
        cube?.material.dispose();
      } catch (e) {}
      try {
        ground?.geometry.dispose();
        ground?.material.dispose();
      } catch (e) {}

      rendererRef.current = null;
      cameraRef.current = null;
      controlsRef.current = null;
      sceneRef.current = null;
      lightingRef.current = null;
      groundRef.current = null;
    };
  }, []);

  return (
    <div className="w-full h-full relative">
      <div ref={containerRef} className="w-full h-full" />
    </div>
  );
}
